+// isReturnedFromParent reports whether makeInst is one of the return values of
+// its enclosing function. Such channels are controlled by callers, not by the
+// local function body, so blocking-op analysis inside the local scope produces
+// false positives.
+func isReturnedFromParent(makeInst *ssa.MakeChan) bool {
+	if makeInst == nil {
+		return false
+	}
+	fn := makeInst.Parent()
+	if fn == nil {
+		return false
+	}
+	for _, bb := range fn.Blocks {
+		for _, instr := range bb.Instrs {
+			ret, ok := instr.(*ssa.Return)
+			if !ok {
+				continue
+			}
+			for _, rv := range ret.Results {
+				if rv == ssa.Value(makeInst) {
+					return true
+				}
+			}
+		}
+	}
+	return false
+}
