+// expandTilde resolves a leading ~/ to the user's home directory so callers
+// don't have to worry about whether the shell expanded it in flag values.
+func expandTilde(p string) string {
+	if !strings.HasPrefix(p, "~/") {
+		return p
+	}
+	home, err := os.UserHomeDir()
+	if err != nil {
+		return p
+	}
+	return filepath.Join(home, p[2:])
+}
