+// lastNodeLoc returns the source location of the last node on a path (where the goroutine exits).
+func lastNodeLoc(p *PPath) string {
+	for i := len(p.Path) - 1; i >= 0; i-- {
+		if p.Path[i].Node != nil && p.Path[i].Node.Instruction() != nil {
+			return fmt.Sprintf("%v", output.GetLoc(p.Path[i].Node.Instruction()))
+		}
+	}
+	return "?"
